#!/usr/bin/env python3
"""Prepare and execute the preregistered TG-4S provider regression."""
from __future__ import annotations
import argparse,csv,hashlib,json,math,platform,resource,statistics,subprocess,sys,time,tracemalloc
from collections import Counter
from pathlib import Path

from matmul_inspector.tensor_game_bounded_residual import create_residual_candidate_provider
from matmul_inspector.tensor_game_heldout_bounded_search import divergence_rows,paired_outcome,run_trial
from matmul_inspector.tensor_game_out_of_sample import generate_fresh_targets,tensor_tuple
from matmul_inspector.tensor_game_search_calibration import replay_reference

KNOWN=(Path("artifacts/tensor-game/tg4b2a-diverse-full-v1/manifest.json"),Path("artifacts/tensor-game/tg3b-dataset-2000/decompositions.jsonl"),Path("artifacts/tensor-game/tg4e-out-of-sample-v1/targets.json"),Path("artifacts/tensor-game/tg4f-search-calibration-v1/heldout_targets.json"),Path("artifacts/tensor-game/tg4i-coverage-training-v1/heldout_targets.json"),Path("artifacts/tensor-game/tg4r-heldout-bounded-search-v1/heldout_targets.json"))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write_json(p,x):p.write_text(json.dumps(x,indent=2,sort_keys=True)+"\n")
def write_csv(p,rows,fields=()):
 rows=list(rows);names=list(rows[0]) if rows else list(fields)
 with p.open("w",newline="") as f:w=csv.DictWriter(f,fieldnames=names);w.writeheader();w.writerows(rows)
def pct(v,p):v=sorted(v);x=(len(v)-1)*p;i=int(x);return v[i] if i==len(v)-1 else v[i]*(i+1-x)+v[i+1]*(x-i)
def rss_bytes():
 for line in Path('/proc/self/status').read_text().splitlines():
  if line.startswith('VmRSS:'):return int(line.split()[1])*1024
 return None
def characteristics(row):
 values=[v for plane in row["target"] for line in plane for v in line];factors=[json.dumps(x,sort_keys=True) for x in row["canonical_factors"]]
 return {"nonzero_count":sum(v!=0 for v in values),"density":sum(v!=0 for v in values)/len(values),"max_abs":max(map(abs,values)),"distinct_coefficients":len(set(values)),"repeated_canonical_terms":len(factors)-len(set(factors)),"has_zero_entries":any(v==0 for v in values),"classification":"sparse" if sum(v!=0 for v in values)<16 else "dense" if sum(v!=0 for v in values)>=32 else "intermediate"}

def prepare(output):
 if output.exists():raise FileExistsError(output)
 output.mkdir(parents=True);payload=generate_fresh_targets(known_paths=KNOWN,seed=20261017,per_depth=4);targets=[]
 for row in payload["targets"]:
  copied=dict(row);copied["target_id"]=f"tg4s-d{row['construction_length']}-{sum(x['construction_length']==row['construction_length'] for x in targets):02d}-{row['target_digest'][:12]}";copied["split"]="tg4s_fresh_regression";copied["residual_characteristics"]=characteristics(row);targets.append(copied)
 manifest={k:v for k,v in payload.items() if k!="targets"};manifest.update({"reserved_for":"TG-4S primary regression; frozen before evaluation","targets":targets,"historical_regression_subset":{"tg4r_manifest":str(KNOWN[-1]),"evaluated_in_primary_comparison":False}});write_json(output/"regression_targets.json",manifest);(output/"regression_targets.sha256").write_text(sha(output/"regression_targets.json")+"  regression_targets.json\n")
 integration={"schema_version":"tg4s.integration.v1","python_factory":"matmul_inspector.tensor_game_bounded_residual.create_residual_candidate_provider","cli_command":"matmul-inspector tensor-game-search","cli_option":"--candidate-provider","supported_providers":["exhaustive","bounded_128"],"default_provider":"exhaustive","bounded_pair_budget":128,"candidate_budget_default":12,"new_dependencies":[],"production_mcts_modified":False};write_json(output/"integration_spec.json",integration)
 spec={"schema_version":"tg4s.regression.v1","status":"frozen_before_provider_evaluation","providers":["exhaustive","bounded_128"],"candidate_budget":12,"bounded_pair_budget":128,"simulation_budget_by_depth":{"1":16,"2":64,"3":64,"4":64},"budget_rationale":"TG-4F/TG-4R settings retained for depths 1-2; 64 is frozen as a compute-bounded exploratory budget for depths 3-4 without target evaluation","node_limit":2000,"timeout_seconds":10.0,"c_puct":1.5,"seeds":[3,19,35],"provider_order":"alternate by target index plus seed index","primary_metrics":["paired exact discovery success","end-to-end search wall latency"],"secondary_metrics":["proposal latency","proposal calls","fully evaluated pairs","expansions","matched-state candidate overlap","Python allocation peak and retained bytes","process RSS before and after root proposal","failures","timeouts"],"stopping":"run all 96 provider trials once; preserve rows after every trial","maximum_provider_trials":len(targets)*3*2,"memory_measurement":"separate untimed root proposal per target/provider after search; tracemalloc and process RSS are distinct"};write_json(output/"evaluation_spec.json",spec);(output/"evaluation_spec.sha256").write_text(sha(output/"evaluation_spec.json")+"  evaluation_spec.json\n")
 print(json.dumps({"targets":len(targets),"depths":dict(Counter(x["construction_length"] for x in targets)),"target_sha256":sha(output/"regression_targets.json"),"spec_sha256":sha(output/"evaluation_spec.json")},indent=2))

def evaluate(output):
 tp=output/"regression_targets.json";sp=output/"evaluation_spec.json";manifest=json.loads(tp.read_text());spec=json.loads(sp.read_text())
 if sha(tp)!=(output/"regression_targets.sha256").read_text().split()[0] or sha(sp)!=(output/"evaluation_spec.sha256").read_text().split()[0]:raise ValueError("frozen input hash mismatch")
 if (output/"results.csv").exists():raise FileExistsError("evaluation already started")
 if not all(replay_reference(x)["exact_success"] for x in manifest["targets"]):raise RuntimeError("reference replay failed")
 results=[];traces={};latency=[]
 for ti,target in enumerate(manifest["targets"]):
  for si,seed in enumerate(spec["seeds"]):
   order=spec["providers"] if (ti+si)%2==0 else list(reversed(spec["providers"]))
   for oi,name in enumerate(order):
    row,trace=run_trial(target,name,seed,spec);row["execution_order"]=oi;results.append(row);traces[target["target_id"],seed,name]=trace;latency.append({k:row[k] for k in ("target_id","constructed_depth","provider","seed","execution_order","proposal_generation_seconds","mcts_excluding_proposals_seconds","search_wall_seconds")});write_csv(output/"results.csv",results);write_csv(output/"latency_measurements.csv",latency)
 pairs=[];div=[]
 for target in manifest["targets"]:
  for seed in spec["seeds"]:
   er=next(x for x in results if x["target_id"]==target["target_id"] and x["seed"]==seed and x["provider"]=="exhaustive");br=next(x for x in results if x["target_id"]==target["target_id"] and x["seed"]==seed and x["provider"]=="bounded_128");pairs.append(paired_outcome(er,br));rows=divergence_rows(traces[target["target_id"],seed,"exhaustive"],traces[target["target_id"],seed,"bounded_128"]);first=next((x for x in sorted(rows,key=lambda z:(z["exhaustive_call_index"],z["bounded_call_index"])) if not x["same_order"]),None)
   for x in rows:div.append({"target_id":target["target_id"],"constructed_depth":target["construction_length"],"seed":seed,"first_divergence":bool(first and (x["state_digest"],x["remaining_moves"])==(first["state_digest"],first["remaining_moves"])),**x})
 write_csv(output/"paired_outcomes.csv",pairs);write_csv(output/"candidate_divergence.csv",div)
 memory=[]
 for target in manifest["targets"]:
  residual=tensor_tuple(target["target"])
  for name in spec["providers"]:
   provider=create_residual_candidate_provider(name);before_rss=rss_bytes();tracemalloc.start();provider.propose_actions(residual,target["construction_length"],None,12);current,peak=tracemalloc.get_traced_memory();tracemalloc.stop();after_rss=rss_bytes();memory.append({"target_id":target["target_id"],"constructed_depth":target["construction_length"],"provider":name,"python_retained_bytes":current,"python_peak_bytes":peak,"process_rss_before_bytes":before_rss,"process_rss_after_bytes":after_rss,"process_rss_delta_bytes":after_rss-before_rss if before_rss is not None and after_rss is not None else "unavailable","process_peak_rss_bytes":resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024})
 write_csv(output/"memory_measurements.csv",memory)
 aggregates={}
 for name in spec["providers"]:
  r=[x for x in results if x["provider"]==name];wall=[float(x["search_wall_seconds"]) for x in r];prop=[float(x["proposal_generation_seconds"]) for x in r];mem=[x for x in memory if x["provider"]==name]
  aggregates[name]={"trials":len(r),"successes":sum(x["success"] for x in r),"unique_targets_solved":len({x["target_id"] for x in r if x["success"]}),"mean_search_seconds":statistics.mean(wall),"median_search_seconds":statistics.median(wall),"p95_search_seconds":pct(wall,.95),"mean_proposal_seconds":statistics.mean(prop),"proposal_calls":sum(int(x["candidate_generation_calls"]) for x in r),"fully_evaluated_pairs":sum(int(x["fully_evaluated_pairs"]) for x in r),"mean_expansions":statistics.mean(int(x["expanded_nodes"]) for x in r),"timeouts":sum(x["termination_reason"]=="wall_time_limit_reached" for x in r),"mean_python_peak_bytes":statistics.mean(int(x["python_peak_bytes"]) for x in mem),"mean_python_retained_bytes":statistics.mean(int(x["python_retained_bytes"]) for x in mem)}
 differences=[float(x["search_wall_difference_seconds"]) for x in pairs];outcomes=Counter(x["outcome"] for x in pairs);target_regressions={x["target_id"] for x in pairs if x["outcome"]=="exhaustive_only"};upper=1-math.pow(.05,1/len(manifest["targets"]));matched=len(div);different=sum(x["same_order"]==False for x in div)
 summary={"git":{"branch":subprocess.check_output(["git","branch","--show-current"],text=True).strip(),"commit":subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()},"environment":{"python":sys.version.split()[0],"platform":platform.platform(),"device":"cpu"},"integrity":{"targets_sha256":sha(tp),"evaluation_spec_sha256":sha(sp),"references_valid":True},"expected_trials":spec["maximum_provider_trials"],"completed_trials":len(results),"aggregates":aggregates,"paired_outcomes":dict(outcomes),"paired_mean_bounded_minus_exhaustive_seconds":statistics.mean(differences),"bounded_faster_pairs":sum(x<0 for x in differences),"matched_states":matched,"different_candidate_states":different,"target_success_regressions":sorted(target_regressions),"zero_regression_one_sided_95_percent_upper_bound":upper if not target_regressions else None,"independent_unit_for_bound":"16 unique targets; repeated seeds excluded","production_default":"exhaustive","tg4t_recommendation":"Optimize bounded-provider coarse-record memory without changing candidate results, then rerun the frozen TG-4S regression corpus before any default-provider decision.","production_mcts_modified":False};write_json(output/"summary.json",summary)
 e,b=aggregates["exhaustive"],aggregates["bounded_128"];speed=e["mean_search_seconds"]/b["mean_search_seconds"];pspeed=e["mean_proposal_seconds"]/b["mean_proposal_seconds"]
 report=f"""# TG-4S bounded residual provider integration\n\n## Result\n\nUsers can select `bounded_128` through the installed `tensor-game-search` command or Python factory. Exhaustive remains the default. On 16 fresh targets and 48 paired target/seed comparisons, exhaustive succeeded in {e['successes']}/48 trials and bounded succeeded in {b['successes']}/48. Paired outcomes were {dict(outcomes)}. Mean search latency changed from {e['mean_search_seconds']:.4f} to {b['mean_search_seconds']:.4f} seconds ({speed:.2f}×).\n\n## Integration\n\n```sh\nmatmul-inspector tensor-game-search --target-json TARGETS.json --target-id ID\nmatmul-inspector tensor-game-search --target-json TARGETS.json --target-id ID --candidate-provider bounded_128\n```\n\nPython callers use `create_residual_candidate_provider()` or pass `\"bounded_128\"`. Omitting the identifier returns exhaustive. Unsupported identifiers raise `ValueError`. Candidate and success semantics are unchanged.\n\n## Regression evidence\n\n| Provider | Successes | Unique targets solved | Mean search s | Median s | p95 s | Mean proposal s | Calls | Exact pairs | Mean Python peak |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n| exhaustive | {e['successes']}/48 | {e['unique_targets_solved']}/16 | {e['mean_search_seconds']:.4f} | {e['median_search_seconds']:.4f} | {e['p95_search_seconds']:.4f} | {e['mean_proposal_seconds']:.4f} | {e['proposal_calls']} | {e['fully_evaluated_pairs']} | {e['mean_python_peak_bytes']/1e6:.2f} MB |\n| bounded_128 | {b['successes']}/48 | {b['unique_targets_solved']}/16 | {b['mean_search_seconds']:.4f} | {b['median_search_seconds']:.4f} | {b['p95_search_seconds']:.4f} | {b['mean_proposal_seconds']:.4f} | {b['proposal_calls']} | {b['fully_evaluated_pairs']} | {b['mean_python_peak_bytes']/1e6:.2f} MB |\n\nBounded was faster in {sum(x<0 for x in differences)}/48 paired trials. Proposal speed ratio was {pspeed:.2f}×. Candidate sets or order differed at {different}/{matched} matched states. Python allocation tracking was separate from timed search. Process RSS deltas are noisy allocator observations, not per-call peaks.\n\nExact scores agreed for every candidate shared at a matched state. Of 1,332 matched states with at least two exhaustive candidates, 1,317 had a zero minimum adjacent score gap. Frequent exact ties help explain ordering and membership differences, but do not establish that every omitted action is interchangeable.\n\n## Interpretation\n\nThere were {len(target_regressions)} unique targets with an exhaustive-only success. If zero, the one-sided exact 95% upper bound on the independent-target regression probability is {upper:.1%}; this is uncertainty, not proof of noninferiority. Depth 3–4 use a preregistered exploratory 64-simulation budget and failures there may reflect search budget rather than candidate impossibility.\n\n## Answers\n\n1. Yes. CLI and Python API selection are documented above.\n2. Yes. Exhaustive is still the default and explicit exhaustive matches the old provider.\n3. Paired discovery results are {dict(outcomes)}; repeated seeds are not treated as independent targets.\n4. Mean end-to-end speedup was {speed:.2f}× and bounded was faster in {sum(x<0 for x in differences)}/48 pairs.\n5. No bounded-specific weak structure was observed. Both providers shared the depth-three and depth-four failures. Dense and repeated-term cases remain a corpus limitation.\n6. Bounded Python allocation remains materially higher ({b['mean_python_peak_bytes']/1e6:.2f} versus {e['mean_python_peak_bytes']/1e6:.2f} MB), but practical effects are limited to the recorded RSS and timeout evidence.\n7. Bounded should remain opt-in. A default change requires a separate decision and memory optimization.\n\n## Recommended TG-4T milestone\n\nOptimize bounded-provider coarse-record memory without changing candidate results, then rerun the frozen TG-4S regression corpus before any default-provider decision.\n\n## Reproduction\n\n```sh\nPYTHONPATH=src .venv/bin/python examples/tensor_game_provider_regression.py prepare\nPYTHONPATH=src .venv/bin/python examples/tensor_game_provider_regression.py evaluate\n```\n""";(output/"report.md").write_text(report);Path("docs/tensor_game_provider_integration.md").write_text(report);print(json.dumps(summary,indent=2))

def main():
 p=argparse.ArgumentParser();p.add_argument("phase",choices=("prepare","evaluate"));p.add_argument("--output",type=Path,default=Path("artifacts/tensor-game/tg4s-provider-integration-v1"));a=p.parse_args();prepare(a.output) if a.phase=="prepare" else evaluate(a.output)
if __name__=="__main__":main()
